/** Local, lazily unlocked synth audio. No profiles, network, subscriptions or game cue names. */
export function createSynthAudio({contextFactory=()=>new(window.AudioContext||window.webkitAudioContext)(),getSettings=()=>({volume:.2,muted:false}),ownsContext=true}={}){let context=null,bus=null,disposed=false;const voices=new Set();function resume(){if(disposed)return null;if(!context){context=contextFactory();bus=context.createGain();bus.connect(context.destination);}if(context.state==='suspended')context.resume();return context;}
 function play({frequency=440,duration=.12,type='triangle',volume=1,delay=0,slide=0}={}){if(disposed||getSettings().muted)return;const ac=resume();if(!ac)return;const settings=getSettings(),t=ac.currentTime+delay,o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.setValueAtTime(frequency,t);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(30,frequency+slide),t+duration);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(Math.max(.001,volume*(settings.volume??.2)),t+.006);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(bus);voices.add(o);o.start(t);o.stop(t+duration+.02);o.onended=()=>{voices.delete(o);o.disconnect();g.disconnect();};}
 return{resume,play,pause(value){if(bus&&context)bus.gain.setTargetAtTime(value?0:1,context.currentTime,.03);},dispose(){if(disposed)return;disposed=true;for(const v of voices){try{v.stop();}catch{}v.disconnect();}voices.clear();bus?.disconnect();if(ownsContext)context?.close();context=null;}};
}
